class CouldNotGetConfigType(Exception):
    """
    Raised when there were no gnbs nor enbs in configuration file
    """
    pass


class IncorrectBTSType(Exception):
    """ Raised when provided BTS type was neither 'GNB' nor 'ENB'. """
    pass


class CouldNotGetSlaveTestPC(Exception):
    """
    Raise when there are no TestPC configured for slave gnb in configuration file
    """
    pass


class RmodCredentialsNotFound(Exception):
    """
    Raised when Radio Unit credentials could not be found for asked sw stream.
    """
    pass


class RmodConfigurationNotFound(Exception):
    """
    Raised when Radio Unit configuration could not be found in init file.
    """
    pass


class TestPCNotFound(Exception):
    """
    Raised when Test PC configuration could not be found in init file.
    """
    pass


class MissingInitParameter(Exception):
    """
    Raised when particular parameter could not be found in init file.
    """
    pass


class SmodSerialNumberUnavailable(Exception):
    """
    Raised when could not find the SMOD serial number for the Test PC.
    """
    pass
